<script setup>
import {computed,ref,watch} from 'vue'
import {agricultureAssetContentUrl} from './api.js'
const props=defineProps({tasks:Array,records:Array,plots:Array,selectedId:String,busy:Boolean,receipt:Object,workspaceId:String})
const emit=defineEmits(['select','create','complete','followup','recheck','dismiss'])
const filter=ref('open')
const item=computed(()=>props.tasks?.find(x=>x.id===props.selectedId))
const visible=computed(()=>props.tasks?.filter(x=>filter.value==='completed'?x.status==='completed':x.status!=='completed')||[])
const count=status=>props.tasks?.filter(x=>status==='completed'?x.status==='completed':x.status!=='completed').length||0
const plot=x=>props.plots?.find(p=>p.id===x?.plotId)?.name||'全部园区'
const lines=computed(()=>item.value?.description?.split(/\n+/).map(x=>x.trim()).filter(Boolean)||[])
const isStep=line=>/^(?:[-*•]\s+|\d+[.)、]\s*)/.test(line)
const clean=line=>line.replace(/\*\*/g,'').replace(/^#+\s*/, '').replace(/^(?:[-*•]\s+|\d+[.)、]\s*)/,'')
const steps=computed(()=>lines.value.filter(isStep).map(clean))
const description=computed(()=>lines.value.filter(line=>!isStep(line)).map(clean).join('\n'))
watch(()=>props.selectedId,()=>{})
</script>
<template><section class="mobile-task-flow">
<template v-if="receipt"><h1>记录已保存</h1><div class="task-speech"><img src="/brand/shuyu-raindrop-v1.png" alt="澍雨助手"><p>记录已保存！<br>你可以根据情况，决定是否复查。</p></div><article class="task-saved"><span>✓ 已完成</span><h2>{{ receipt.title }}</h2><p>{{ receipt.note }}</p><div class="saved-photos"><img v-for="id in receipt.assetIds || []" :key="id" :src="agricultureAssetContentUrl(workspaceId,id)" alt="本次完成记录关联照片"></div></article><aside>完成检查，不代表问题已经解决，建议结合后续观察持续关注。</aside><h2>还需要复查吗？</h2><button class="task-option" @click="emit('recheck',receipt)">⊕ 新建复查待办 <small>再设置一个时间点提醒自己</small></button><button class="task-option" @click="emit('followup',receipt)">◷ 设置助手跟进 <small>按你确认的次数和预算执行</small></button><button @click="emit('dismiss')">返回待办</button></template>
<template v-else-if="item"><header class="task-detail-header"><button class="task-back" aria-label="返回待办" @click="emit('select','')">‹</button><h1>{{ item.title }}</h1></header><p class="task-location">{{ item.status==='completed'?'已完成':'待处理' }} · {{ plot(item) }}</p><div class="task-illustration"><span>现场检查 · 插画示意</span></div><h2>任务说明</h2><p class="task-description">{{ description || '请按任务步骤完成检查并记录实际情况。' }}</p><h2 v-if="steps.length">按以下步骤完成检查</h2><article v-for="(step,index) in steps" :key="index" class="task-step"><b>{{ index+1 }}</b><span>{{ step }}</span></article><button v-if="item.status!=='completed'" class="agri-primary" :disabled="busy" @click="emit('complete',item)">我已检查，写记录</button><article v-for="record in records?.filter(r=>r.workItemId===item.id)" :key="record.id" class="task-saved"><h2>完成记录</h2><p>{{ record.note }}</p><div class="saved-photos"><img v-for="id in record.assetIds || []" :key="id" :src="agricultureAssetContentUrl(workspaceId,id)" alt="完成记录关联照片"></div></article></template>
<template v-else><header><h1>待办任务</h1><button aria-label="新建任务" @click="emit('create')">⊕</button></header><p class="task-location">我的园区 · 现场待办</p><nav><button :class="{active:filter==='open'}" @click="filter='open'">待处理 {{ count('open') }}</button><button :class="{active:filter==='completed'}" @click="filter='completed'">已完成 {{ count('completed') }}</button></nav><article v-for="(task,index) in visible" :key="task.id" class="task-summary" :class="{featured:index===0}"><div class="task-summary-top"><div class="task-thumb" aria-label="农事插画示意"></div><div><h2>{{ task.title }}</h2><small>⌖ {{ plot(task) }} · {{ task.dueAt?new Date(task.dueAt*1000).toLocaleDateString():'未设截止时间' }}</small></div></div><button v-if="index===0" class="agri-primary" @click="emit('select',task.id)">查看任务 →</button><button v-else class="task-card-link" @click="emit('select',task.id)" :aria-label="`查看${task.title}`">查看任务 ›</button></article><p v-if="!visible.length">当前没有{{ filter==='open'?'待处理':'已完成' }}任务</p><div class="task-speech"><img src="/brand/shuyu-raindrop-v1.png" alt="澍雨助手"><p>先完成眼前的事，<br>有记录才好判断下一步。</p></div></template>
</section></template>
<style scoped>
