background:#fffdf0;font-size:12px}.task-description{white-space:pre-wrap;font-size:16px;line-height:1.65}.task-step{padding:14px;border:1px solid #e7eee8;border-radius:14px;display:flex;gap:14px;margin:9px 0;background:white;font-size:16px;line-height:1.5}.task-step b{color:#165442}.task-detail-header{position:sticky;top:-8px;background:white;z-index:2;gap:10px;justify-content:flex-start!important}.task-detail-header h1{font-size:22px;flex:1}.task-detail-header .task-back{font-size:32px;padding:0;width:32px}.task-step{font-size:14px}.task-description{font-size:15px;line-height:1.55}.task-option{display:block;width:100%;text-align:left;background:white!important;border:1px solid #e7eee8!important;margin:12px 0;padding:14px}.task-option small{display:block;font-size:13px;margin-top:6px;color:#6b7e78}.task-saved{padding:16px;background:#f0faee;border-radius:16px;margin:14px 0;white-space:pre-wrap}.mobile-task-flow aside{padding:14px;background:#fff7e2;border-radius:14px;font-size:14px;line-height:1.6}}
</style>
